CREATE TABLE categories (category_id UUID PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT,parent_category_id UUID REFERENCES categories(category_id),active BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE brands (brand_id UUID PRIMARY KEY,name VARCHAR(100) NOT NULL,slug VARCHAR(120) NOT NULL UNIQUE,description TEXT,active BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE TABLE products (product_id UUID PRIMARY KEY,sku VARCHAR(100) NOT NULL UNIQUE,name VARCHAR(200) NOT NULL,slug VARCHAR(220) NOT NULL UNIQUE,short_description VARCHAR(500),description TEXT,category_id UUID NOT NULL REFERENCES categories(category_id),brand_id UUID REFERENCES brands(brand_id),price NUMERIC(19,4) NOT NULL CHECK(price>=0),currency VARCHAR(3) NOT NULL,status VARCHAR(20) NOT NULL,active BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL);
CREATE INDEX idx_products_category ON products(category_id);CREATE INDEX idx_products_brand ON products(brand_id);CREATE INDEX idx_products_status ON products(status);CREATE INDEX idx_products_active ON products(active);
CREATE TABLE product_images (image_id UUID PRIMARY KEY,product_id UUID NOT NULL REFERENCES products(product_id),url TEXT NOT NULL,alt_text VARCHAR(255),sort_order INTEGER NOT NULL,primary_image BOOLEAN NOT NULL,created_at TIMESTAMPTZ NOT NULL);CREATE INDEX idx_images_product ON product_images(product_id);
CREATE TABLE product_attributes (attribute_id UUID PRIMARY KEY,product_id UUID NOT NULL REFERENCES products(product_id),attribute_name VARCHAR(100) NOT NULL,attribute_value VARCHAR(500) NOT NULL,created_at TIMESTAMPTZ NOT NULL);CREATE INDEX idx_attributes_product ON product_attributes(product_id);
